#nullable enable // autogenerated

using MVZ2.Metas;
using MVZ2.Resources;
using PVZEngine;
using UnityEngine;

namespace MVZ2.ResourcePacks
{
    public class ModifiedCharacterVariant : ITalkCharacterVariant
    {
        public ModifiedCharacterVariant(NamespaceID id, ITalkCharacterLayer[] layers)
        {
            ID = id;
            Layers = layers;
        }

        public NamespaceID ID { get; }
        public XMLConditionList? Unlock { get; set; }
        public int Width { get; set; }
        public int Height { get; set; }
        public float PivotX { get; set; }
        public float PivotY { get; set; }
        public Vector2 WidthExtend { get; set; }
        public ITalkCharacterLayer[] Layers { get; }

        public ITalkCharacterLayer[] GetLayers()
        {
            return Layers;
        }
    }
}
